class AVAERPriceListToAzureBlobService  extends SysOperationServiceBase
{

}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_dataContract">_dataContract</param>
void runService(AVAERPriceListToAzureBlobContract _dataContract)
{
    String255       priceGroupFilterStr = _dataContract.parmpriceGroupFilterStr();
    AVAPriceIncreasePriceDiscGroup     priceIncreasePriceDiscGroup;

    Query                   query  = new Query();
    QueryBuildDataSource    priceDiscGrpDS = query.addDataSource(tableNum(PriceDiscGroup));
    QueryBuildDataSource    priceIncreasePriceDiscGroupDS = priceDiscGrpDS.addDataSource(tablenum(AVAPriceIncreasePriceDiscGroup));
    priceIncreasePriceDiscGroupDS.addRange(fieldNum(AVAPriceIncreasePriceDiscGroup,PriceIncreaseSet)).value(_dataContract.parmPriceIncreaseSet());
    priceIncreasePriceDiscGroupDS.relations(true);


    priceDiscGrpDS.addRange(fieldNum(PriceDiscGroup,GroupId)).value(priceGroupFilterStr);
    priceDiscGrpDS.addRange(fieldNum(PriceDiscGroup,Type)).value(enum2str(PriceGroupType::PriceGroup));
    PriceDiscGroup      priceDiscGroup;

    QueryRun        queryRun = new QueryRun(query);

    while (queryRun.next())
    {
        priceDiscGroup = queryRun.get(tableNum(PriceDiscGroup));
        priceIncreasePriceDiscGroup = queryRun.get(tableNum(AVAPriceIncreasePriceDiscGroup));

        if (priceDiscGroup)
        {
           // notPostedJour = PriceDiscGroup.AVAcheckNotPostedJour();
            if (priceIncreasePriceDiscGroup.JournalNum != '' && !priceIncreasePriceDiscGroup.isJourPosted())
            {
                Error(strFmt("@NDX:NXAPriceNotPostedJour",'1'));
            }
            else
            {
                AVAERPriceListController::constructForAzureBlob(priceDiscGroup.GroupId);
            }
        }
    }    
}
